import json

with open('/home/ubuntu/.claude-account-3/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-13-projects-contamcal-irt-calibration--claude-sessions-paper-agent-8415d3a6/f5d05f64-02bd-4c69-b131-067a64259496/tool-results/mcp-agent-ml-research-read_registry-1779018635264.txt') as f:
    outer = json.load(f)

registry = json.loads(outer['result'])
exps = registry['data']['experiments']

# Comprehensive: find ALL experiments across entire registry with MAE data
for exp_id, exp_data in sorted(exps.items()):
    metrics = exp_data.get('metrics', {})
    if not isinstance(metrics, dict):
        continue
    metrics_str = json.dumps(metrics).lower()
    if 'mae' in metrics_str:
        # Collect MAE values
        mae_vals = {}
        for k, v in metrics.items():
            kl = k.lower()
            if 'mae' in kl:
                mae_vals[k] = v
            if isinstance(v, dict):
                for k2, v2 in v.items():
                    if 'mae' in k2.lower():
                        mae_vals[f"{k}.{k2}"] = v2
        # Also check for baselines sub-dict
        if 'baselines' in metrics:
            for bk, bv in metrics['baselines'].items():
                mae_vals[f"baselines.{bk}"] = bv
        if 'baselines_mae' in metrics:
            for bk, bv in metrics['baselines_mae'].items():
                mae_vals[f"baselines_mae.{bk}"] = bv
        if mae_vals:
            status = exp_data.get('status', '?')
            conclusion = exp_data.get('conclusion', '?')
            print(f"{exp_id}  [status={status}, conclusion={conclusion}]")
            for mk, mv in sorted(mae_vals.items()):
                print(f"  {mk}: {mv}")
            print()
